    if not intervals:
        return []

    intervals.sort(key=lambda x: (x[0] - x[1], x[1] - x[0]))

    result = []
    current = intervals[0]

    for i in range(1, len(intervals)):
        if intervals[i][0] <= current[1]:
            current = (current[0], max(current[1], intervals[i][1]))
        else:
            result.append(current)
            current = (current[0], max(current[1], intervals[i][1]))

    result.append(current)
    return result

